# codec plugin

/*
Codec Plugin 可以支持在 Codec 中自定义编码解码，自定义 Bypass 与字符串处理函数

函数定义非常简单

func(i: string) string
*/
Bypass403Header = {"X-Originating-IP":"127.0.0.1","X-Remote-IP":"127.0.0.1","X-Client-IP":"127.0.0.1","X-Forwarded-For":"127.0.0.1","X-Forwared-Host":"127.0.0.1","X-Host":"127.0.0.1","X-Custom-IP-Authorization":"127.0.0.1"}

handle = func(origin /*string*/) {
    # handle your origin str
    freq, err = fuzz.HTTPRequest(origin)
    if err != nil{
        return origin
    }
    for k,v = range Bypass403Header{
        freq = freq.FuzzHTTPHeader(k,v)
    }
    
    return string(freq.FirstHTTPRequestBytes())
}
